import org.junit.Test;
import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class CommentsConfigurationTest {

    @Test public void givenEmptyMap_thenReturnsEmptyMap() {
        CommentsConfiguration comments = new CommentsConfiguration();
        Map<String, List<String>> map = comments.getAllComments();
        assertTrue(map.isEmpty());
    }

    @Test public void givenCommentsMap_thenReturnsUnmodifiableMap() {
        Map<String, List<String>> comments = new HashMap<>();
        comments.put("path", Arrays.asList("comment1"));
        CommentsConfiguration cfg = new CommentsConfiguration(comments);
        Map<String, @UnmodifiableView List<String>> map = cfg.getAllComments();
        assertFalse(map.isEmpty());
        assertTrue(map.containsKey("path"));
    }

    @Test public void givenNonEmptyCommentLines_thenSetsCorrectCommentLines() {
        Map<String, List<String>> comments = new HashMap<>();
        CommentsConfiguration cfg = new CommentsConfiguration(comments);
        cfg.setComment("path", "comment1\ncomment2");
        Map<String, @UnmodifiableView List<String>> map = cfg.getAllComments();
        assertTrue(map.containsKey("path"));
        assertEquals(Arrays.asList("comment1", "comment2"), map.get("path"));
    }

